# Latent -log10(Kd) over all 1024 genotypes, indexed by the bitmask of mutated sites
def predict_latent(terms):
    n = 1 << 10
    idx = np.arange(n)
    y = np.zeros(n)
    for st, c in terms:
        if not st:
            y += c
            continue
        mask = 0
        for s in st:
            mask |= (1 << s)
        y += c * ((idx & mask) == mask)
    return y

# In-place fast Walsh-Hadamard transform; unnormalized, so divide by n for coefficient
def fwht(a):
    a = np.asarray(a, float).copy()
    n = len(a); h = 1
    while h < n:
        for i in range(0, n, h * 2):
            x = a[i:i+h].copy(); y = a[i+h:i+2*h].copy()
            a[i:i+h] = x + y
            a[i+h:i+2*h] = x - y
        h *= 2
    return a

# Raw incremental percent of observed variance explained by each interaction order
def variance_by_order(ab, ag):
    pf = find_param_file(ab, ag)
    if pf is None:
        return None
    idx, obs = load_observed(ab, ag)
    if idx is None or len(obs) == 0:
        return None
    ss_tot = float(((obs - obs.mean()) ** 2).sum())
    if ss_tot == 0:
        return None
    n = 1 << 10
    fhat = fwht(predict_latent(load_terms(pf))) / n
    order = np.array([bin(s).count("1") for s in range(n)])
    nz = np.abs(fhat) > 1e-9
    max_order = int(order[nz].max()) if nz.any() else 0
    r2 = {0: 0.0}   # observed mean is the reference, so order 1 covers the whole additive model
    for k in range(1, max_order + 1):
        pred = fwht(fhat * (order <= k))[idx]   # best order<=k approximation of the landscape
        if censor_floor is not None:
            pred = np.maximum(pred, censor_floor)
        r2[k] = 1.0 - float(((obs - pred) ** 2).sum()) / ss_tot
    inc = {k: 100.0 * (r2[k] - r2[k - 1]) for k in range(1, max_order + 1)}
    for k in range(max_order + 1, 11):
        inc[k] = 0.0
    return inc

# Display segments: cumulative R2 floored at zero and forced monotone
def explained_by_order(ab, ag):
    inc = variance_by_order(ab, ag)
    if inc is None:
        return None
    cum = np.cumsum([inc[k] for k in range(1, 11)])
    seg, prev, rmax = {}, 0.0, 0.0
    for i, k in enumerate(range(1, 11)):
        rmax = max(rmax, cum[i])
        val = max(rmax, 0.0)
        seg[k] = max(val - prev, 0.0)
        prev = val
    return seg

def censored_frac(ab, ag):
    idx, obs = load_observed(ab, ag)
    if obs is None:
        return None
    return float((obs <= censor_floor + 1e-3).mean())

def panel_orders(antibodies):
    mx = 0
    for ab in antibodies:
        for ag in antigen_order:
            pf = find_param_file(ab, ag)
            if pf is not None:
                mx = max(mx, max((len(s) for s, _ in load_terms(pf)), default=0))
    return list(range(1, max(mx, 1) + 1))

# Per-complex full-model R2 and censoring (these measures are used to decide whether to include)

def inclusion_table():
    """s."""
    rows = []
    for ab in all_antibodies:
        for ag in antigen_order:
            inc = variance_by_order(ab, ag)
            rows.append(dict(antibody=ab, antigen=ag,
                             r2_pct=None if inc is None else sum(inc[k] for k in range(1, 11)),
                             censored=censored_frac(ab, ag)))
    return pd.DataFrame(rows)

# Keep an antibody only when both of its complexes clear the R2 and censoring thresholds
def select_antibodies(tab):
    keep = []
    for ab in all_antibodies:
        sub = tab[tab.antibody == ab]
        if sub.r2_pct.isna().any() or sub.censored.isna().any():
            continue
        if sub.r2_pct.min() > min_r2_pct and sub.censored.max() <= max_censored_frac:
            keep.append(ab)
    return keep
